// State is a session's lifecycle state.
//
//	starting -> idle <-> running
//	idle|running -> closing -> closed
//	starting|idle|running -> failed   (the runtime died)
type SessionState string

const (
	SessionStateClosed     SessionState = "closed"
	SessionStateClosing    SessionState = "closing"
	SessionStateFailed     SessionState = "failed"
	SessionStateIdle       SessionState = "idle"
	SessionStateRunning    SessionState = "running"
	SessionStateStarting   SessionState = "starting"
	SessionStateSuspended  SessionState = "suspended"
	SessionStateSuspending SessionState = "suspending"
)

type SessionTagsParams struct {
	SessionID string   `json:"sessionId"`
	Tags      []string `json:"tags"`
}

// SessionUpdatedData is a snapshot of the mutable session fields. Optional
// fields that are absent have been cleared, rather than left unchanged.
// State uses the session lifecycle names (idle, running, closing, ...).
type SessionUpdatedData struct {
	ActiveTurnID string        `json:"activeTurnId,omitempty"`
	Archived     bool          `json:"archived,omitempty"`
	Budget       *BudgetLimits `json:"budget,omitempty"`
	// Config contains current session defaults, never a one-turn override.
	Config           *TurnConfig       `json:"config,omitempty"`
	Error            *ErrorInfo        `json:"error,omitempty"`
	ForkPending      bool              `json:"forkPending,omitempty"`
	LastStatus       TurnStatus        `json:"lastStatus,omitempty"`
	Metadata         map[string]string `json:"metadata,omitempty"`
	Pinned           bool              `json:"pinned,omitempty"`
	RuntimeSessionID string            `json:"runtimeSessionId,omitempty"`
	// SettingsRevision changes only when session settings or pinning change.
	SettingsRevision uint64       `json:"settingsRevision,omitempty"`
	State            string       `json:"state"`
	Title            string       `json:"title"`
	Turns            int          `json:"turns"`
	UpdatedAt        time.Time    `json:"updatedAt"`
	Usage            *BudgetUsage `json:"usage,omitempty"`
}

// Field describes a field for settings interfaces. When describes the global
// lifetime; scoped snapshots can refine it using adapter capabilities.
type SettingsField struct {
	Minimum  *int64   `json:"minimum,omitempty"`
	Nullable bool     `json:"nullable,omitempty"`
	Scopes   []string `json:"scopes"`
	Type     string   `json:"type"`
	Unit     string   `json:"unit,omitempty"`
	When     string   `json:"when"`
	Writable bool     `json:"writable"`
}

// SettingsGetParams select host settings or a session's settings.
type SettingsGetParams struct {
	Target SettingsTarget `json:"target,omitempty"`
}

// Omitted fields remain unchanged. Null disables nullable limits; false and zero are explicit values.
type SettingsPatch map[string]json.RawMessage

type SettingsSnapshot struct {
	Deferred []string                 `json:"deferred,omitempty"`
	Fields   map[string]SettingsField `json:"fields"`
	// Resync means a slow observer missed one or more notifications, possibly
	// for another target. Refresh displayed targets with settings.get.
	Resync   bool           `json:"resync,omitempty"`
	Revision uint64         `json:"revision"`
	Target   SettingsTarget `json:"target,omitempty"`
	Values   SettingsValues `json:"values"`
}

type SettingsTarget struct {
	SessionID string `json:"sessionId,omitempty"`
}

// Values is the single settings document. Process describes host wiring and
// shutdown policy; Session supplies defaults for new sessions. Scoped snapshots replace
// Session with the selected session's settings. Optional limits use nil for no
// limit; a zero cache budget retains no cached events. These are data budgets,
// not limits on process RSS or memory owned by child processes.
type SettingsValues struct {
	Approvals ApprovalSettings  `json:"approvals"`
	Budget    BudgetLimits      `json:"budget"`
	History   HistorySettings   `json:"history"`
	Logging   LoggingSettings   `json:"logging"`
	Memory    MemorySettings    `json:"memory"`
	Process   ProcessSettings   `json:"process"`
	Session   SessionSettings   `json:"session"`
	Streams   StreamSettings    `json:"streams"`
	Workspace WorkspaceSettings `json:"workspace"`
}

