// TurnCompletedData is the payload of turn.completed. Exactly one
// turn.completed is emitted for every turn.started.
type TurnCompletedData struct {
	Budget        *BudgetExceeded `json:"budget,omitempty"`
	Error         *ErrorInfo      `json:"error,omitempty"`
	RuntimeTurnID string          `json:"runtimeTurnId,omitempty"`
	Status        TurnStatus      `json:"status"`
	Usage         *UsageData      `json:"usage,omitempty"`
}

// Settings is a complete selection for a turn. Empty Model/Effort delegate
// selection to the runtime. Options use the adapter's native names. Values are
// replaced as a whole: there is no implicit recursive merge of native options.
type TurnConfig struct {
	Effort  string                     `json:"effort,omitempty"`
	Model   string                     `json:"model,omitempty"`
	Options map[string]json.RawMessage `json:"options,omitempty"`
}

// TurnStartedData is the payload of turn.started.
type TurnStartedData struct {
	Budget *BudgetLimits `json:"budget,omitempty"`
	// Config is the accepted effective turn selection after native resolution.
	Config *TurnConfig `json:"config,omitempty"`
	// Input preserves content order and local image references for replay.
	// Image bytes are not copied into the transcript.
	Input []InputPart `json:"input,omitempty"`
	// Text is the concatenated text of the prompt input.
	Text      string             `json:"text,omitempty"`
	Workspace *WorkspaceSettings `json:"workspace,omitempty"`
}

// TurnStatus is the final status of a turn.
type TurnStatus string

const (
	TurnStatusCancelled TurnStatus = "cancelled"
	TurnStatusCompleted TurnStatus = "completed"
	TurnStatusFailed    TurnStatus = "failed"
)

// UsageData reports token usage and, where the runtime provides it, cost.
type UsageData struct {
	CacheWriteTokens  int64 `json:"cacheWriteTokens,omitempty"`
	CachedInputTokens int64 `json:"cachedInputTokens,omitempty"`
	ContextWindow     int64 `json:"contextWindow,omitempty"`
	// CostUSD is the runtime's own estimate, not a bill.
	CostUSD     *float64 `json:"costUsd,omitempty"`
	InputTokens int64    `json:"inputTokens,omitempty"`
	// Mode is "snapshot" (default) or "delta". Snapshots are cumulative within
	// Scope and repeated snapshots are not additional usage. Deltas are increments.
	Mode            string `json:"mode,omitempty"`
	OutputTokens    int64  `json:"outputTokens,omitempty"`
	ReasoningTokens int64  `json:"reasoningTokens,omitempty"`
	// Scope is "turn" (this turn only) or "session" (cumulative).
	Scope string `json:"scope"`
	// TokensKnown distinguishes a reported zero from unknown token accounting.
	// ContextWindow is never a token-usage measurement.
	TokensKnown bool `json:"tokensKnown,omitempty"`
	// TotalTokens is the normalized consumed-token total, including cache reads
	// and writes where they are separate. Cached/reasoning counts may be subsets
	// of input/output; consumers must not add those fields to TotalTokens.
	TotalTokens int64 `json:"totalTokens,omitempty"`
}

// Binding is durable identity data. Owned means the backend created a dedicated
// worktree for SessionID; it is not permission to delete dirty files.
type WorkspaceBinding struct {
	BaseCommit string `json:"baseCommit,omitempty"`
	CommonDir  string `json:"commonDir"`
	GitDir     string `json:"gitDir"`
	Kind       string `json:"kind"`
	Owned      bool   `json:"owned"`
	Path       string `json:"path"`
	Repo       string `json:"repo"`
	SessionID  string `json:"sessionId"`
}

// Diff compares content at turn boundaries. WorkingTree includes nonignored
// untracked files; Index separately shows changes to staged content.
type WorkspaceDiff struct {
	After         *WorkspaceSnapshot `json:"after,omitempty"`
	Before        *WorkspaceSnapshot `json:"before,omitempty"`
	Binding       WorkspaceBinding   `json:"binding"`
	Complete      bool               `json:"complete"`
	EncodingLossy bool               `json:"encodingLossy,omitempty"`
	Error         string             `json:"error,omitempty"`
	Index         string             `json:"index"`
	MaxDiffBytes  int64              `json:"maxDiffBytes"`
	SessionID     string             `json:"sessionId"`
	Truncated     bool               `json:"truncated"`
	TurnID        string             `json:"turnId"`
	WorkingTree   string             `json:"workingTree"`
}

// Settings is the workspace group in the kit's single settings document.
// Location fields apply to new sessions; capture policy applies to future turns.
type WorkspaceSettings struct {
	Base             string `json:"base"`
	CaptureDiff      bool   `json:"captureDiff"`
	MaxDiffBytes     int64  `json:"maxDiffBytes"`
	MaxFiles         int    `json:"maxFiles"`
	MaxSnapshotBytes int64  `json:"maxSnapshotBytes"`
	// "existing" (default) or "worktree"
	Mode      string `json:"mode"`
	Path      string `json:"path"`
	Repo      string `json:"repo"`
	Root      string `json:"root"`
	TimeoutMs int64  `json:"timeoutMs"`
}

// Settings is the workspace group in the kit's single settings document.
// Location fields apply to new sessions; capture policy applies to future turns.
type WorkspaceSettingsPatch map[string]json.RawMessage

// Snapshot references durable content objects in the repository. Capture does
// not change the user's index, HEAD or worktree contents.
type WorkspaceSnapshot struct {
	Bytes      int64     `json:"bytes"`
	CapturedAt time.Time `json:"capturedAt"`
	Files      int       `json:"files"`
	Head       string    `json:"head,omitempty"`
	Index      string    `json:"index"`
	Tree       string    `json:"tree"`
}
